const SKILL_TREE_UF_BOUNDS_10F = {
  'crystalpony|damageTakenMult': { min:-0.3,  max:0.6 },
  'crystalpony|radius':          { min:-2,    max:2 },
  'mule|damageTakenMult':        { min:-0.25, max:0.6 },
  'mule|radius':                 { min:-2,    max:2 },
  'alicorn|damageTakenMult':     { min:-0.25, max:0.6 },
  'alicorn|radius':              { min:-2,    max:2 },
};

function ST10F(classId, stat, amount, perRank){
  const e = { type:'stat', classId, stat, amount };
  if (perRank != null) e.perRank = perRank;
  return e;
}
function UF10F(classId, field, amount){
  const b = SKILL_TREE_UF_BOUNDS_10F[classId + '|' + field];
  return { type:'uniqueField', classId, field, amount, min:b.min, max:b.max };
}
function FL10F(classId, field, value){ return { type:'uniqueFlag', classId, field, value }; }
function SY10F(classId, stat, perOwned, tag){ return { type:'synergyStat', classId, stat, perOwned, tag }; }

